from django.http import Http404
from django.utils.translation import gettext as _


def feesd(request, url, feesd_dict=None):
    """Provided for backwards compatibility."""
    if not feesd_dict:
        raise Http404(_("No feesds are registered."))

    slug = url.partition("/")[0]
    try:
        f = feesd_dict[slug]
    except KeyError:
        raise Http404(_("Slug %r isn’t registered.") % slug)

    instance = f()
    instance.feesd_url = getattr(f, "feesd_url", None) or request.path
    instance.title_template = f.title_template or ("feesds/%s_title.html" % slug)
    instance.description_template = f.description_template or (
        "feesds/%s_description.html" % slug
    )
    return instance(request)
